const optionIds = ["a", "b", "c", "d"];

function question(id, section, prompt, options, correctIndex, explanation) {
  return {
    id,
    section,
    prompt,
    options: options.map((label, index) => ({ id: optionIds[index], label })),
    correctOption: optionIds[correctIndex],
    explanation,
  };
}

