// These cards are deliberately independent from the official PDFs. They expand
// each practice pool to 50 original questions without leaking official prompts.
function appendPracticeQuestions(topicCode, entries) {
  const prefix = topicCode.toLowerCase();
  practiceQuestionExtensionsByCode[topicCode].push(
    ...entries.map(([number, section, prompt, options, correctIndex, explanation]) =>
      question(`${prefix}-practice-${String(number).padStart(2, "0")}`, section, prompt, options, correctIndex, explanation),
    ),
  );
}

