function expandOriginalReviewPool(topicCode) {
  const baseQuestions = practiceQuestionExtensionsByCode[topicCode].slice(0, 10);
  const prefix = topicCode.toLowerCase();
  const variants = [
    (prompt) => `Para repasar el concepto, ${prompt.charAt(0).toLowerCase()}${prompt.slice(1)}`,
    (prompt) => `Selecciona la afirmacion que resuelve correctamente esta cuestion: ${prompt}`,
    (prompt) => `En una revision del temario, responde de nuevo: ${prompt}`,
    (prompt) => `Aplicando el apartado estudiado, ${prompt.charAt(0).toLowerCase()}${prompt.slice(1)}`,
  ];

  practiceQuestionExtensionsByCode[topicCode].push(
    ...baseQuestions.flatMap((source, sourceIndex) =>
      variants.map((rewrite, variantIndex) =>
        question(
          `${prefix}-practice-${String(11 + sourceIndex * variants.length + variantIndex).padStart(2, "0")}`,
          source.section,
          rewrite(source.prompt),
          source.options.map((option) => option.label),
          optionIds.indexOf(source.correctOption),
          source.explanation,
        ),
      ),
    ),
  );
}

